function updateIn(obj, path, fn) {
  let target = obj;
  for (const key of path.slice(0, -1)) target = target[key];
  target[path[path.length - 1]] = fn(target[path[path.length - 1]]);
  return obj;
}

solution.solution.js:
function updateIn(obj, path, fn) {
  if (path.length === 0) return fn(obj);
  const [key, ...rest] = path;
  const current = obj === undefined || obj === null ? {} : obj;
  const child = updateIn(current[key], rest, fn);
  if (Array.isArray(current)) {
    const copy = current.slice();
    copy[key] = child;
    return copy;
  }
  return { ...current, [key]: child };
}

unitTests:
test("changes the nested value in a copy", () => {
  const state = { user: { name: "Ada", stats: { level: 3 } }, items: [] };
  const next = updateIn(state, ["user", "stats", "level"], n => n + 1);
  checkEq(next.user.stats.level, 4);
  checkEq(state.user.stats.level, 3);
});

test("unchanged branches are shared, changed ones copied", () => {
  const state = { a: { x: 1 }, b: { y: 2 } };
  const next = updateIn(state, ["a", "x"], () => 9);
  check(next.b === state.b);
  check(next.a !== state.a);
  check(next !== state);
});

test("arrays stay arrays", () => {
  const state = { list: [1, 2, 3] };
  const next = updateIn(state, ["list", 1], n => n * 10);
  checkEq(next.list, [1, 20, 3]);
  check(Array.isArray(next.list));
  checkEq(state.list, [1, 2, 3]);
});

test("missing objects are created", () => {
  checkEq(updateIn({}, ["a", "b"], () => 1), { a: { b: 1 } });
});

test("empty path", () => {
  checkEq(updateIn(5, [], n => n + 1), 6);
});

